package bench.paths.sers;

import tools.jackson.core.JsonGenerator;
import tools.jackson.core.SerializableString;
import tools.jackson.core.io.SerializedString;
import tools.jackson.databind.SerializationContext;

import org.openjdk.jmh.annotations.CompilerControl;

import bench.paths.beans.GenPerson;

/**
 * Hand-written stand-in for the serializer Quarkus generates for {@link GenPerson}, replicating the
 * generated bytecode rather than an idealised version of it. Per property the generated code does:
 *
 * <pre>
 *   getter -&gt; box (primitives) -&gt; SerializationInclude.shouldSerialize(Object)
 *          -&gt; JacksonMapperUtil.writeFieldName(gen, namingStrategy, name, SerializedString)
 *          -&gt; writeString / writeNumber
 * </pre>
 *
 * and it emits properties <b>alphabetically</b>: {@code age, firstName, height, lastName}. That
 * ordering is what puts {@code writeNumber(double)} between the two {@code writeString} calls.
 *
 * <p>The two helpers are kept out of line deliberately. In the generated code
 * {@code shouldSerialize} is 76 bytes, over the default {@code MaxInlineSize} of 35, so C2 leaves
 * it as a call - four of them per object. Letting it inline here would not reproduce the compiled
 * shape being studied.
 *
 * <p>{@code serialize} itself is not inlined for the same reason as {@link Mixed4Ser} and master's
 * {@code FlatSer}: it keeps the copy loops in this method instead of burying them inside
 * {@code CollectionSerializer}.
 */
public final class GenPersonSer extends GeneratedSer<GenPerson> {

    private static final SerializedString AGE = new SerializedString("age");
    private static final SerializedString FIRST_NAME = new SerializedString("firstName");
    private static final SerializedString HEIGHT = new SerializedString("height");
    private static final SerializedString LAST_NAME = new SerializedString("lastName");

    public GenPersonSer() { super(GenPerson.class); }

    /** Stand-in for {@code JacksonMapperUtil$SerializationInclude.shouldSerialize}. */
    private static boolean shouldSerialize(Object value) {
        return value != null;
    }

    /** Stand-in for {@code JacksonMapperUtil.writeFieldName}. */
    private static void writeFieldName(JsonGenerator g, String name, SerializableString encoded) {
        g.writeName(encoded);
    }

    @CompilerControl(CompilerControl.Mode.DONT_INLINE)
    @Override
    public void serializeContent(GenPerson v, JsonGenerator g, SerializationContext ctxt) {
        int age = v.getAge();
        if (shouldSerialize(Integer.valueOf(age))) {
            writeFieldName(g, "age", AGE);
            g.writeNumber(age);
        }
        String firstName = v.getFirstName();
        if (shouldSerialize(firstName)) {
            writeFieldName(g, "firstName", FIRST_NAME);
            g.writeString(firstName);
        }
        double height = v.getHeight();
        if (shouldSerialize(Double.valueOf(height))) {
            writeFieldName(g, "height", HEIGHT);
            g.writeNumber(height);
        }
        String lastName = v.getLastName();
        if (shouldSerialize(lastName)) {
            writeFieldName(g, "lastName", LAST_NAME);
            g.writeString(lastName);
        }
    }
}
